package com.travelmate.app;
import org.junit.Test;import static org.junit.Assert.*;
public class VoicePolicyTest {
 @Test public void hebrewLocaleRanking(){assertEquals(2,VoicePolicy.hebrewRank("he-IL"));assertEquals(2,VoicePolicy.hebrewRank("iw-IL"));assertEquals(1,VoicePolicy.hebrewRank("he"));assertEquals(0,VoicePolicy.hebrewRank("en-US"));}
 @Test public void strictStopCommands(){for(String value:new String[]{"עצור","תעצור","תפסיק","די"," stop! "})assertTrue(VoicePolicy.stopCommand(value));for(String value:new String[]{"אל תעצור","כדאי לעצור כאן","stop at the museum","", "אולי די"})assertFalse(VoicePolicy.stopCommand(value));}
 @Test public void interruptRequiresForegroundPermissionAndAuthorizedCurrentSpeech(){String speech="voice-document123-1",mic="voice-document123-2";assertTrue(VoicePolicy.interruptAllowed(true,true,true,mic,speech,speech,speech));assertFalse(VoicePolicy.interruptAllowed(false,true,true,mic,speech,speech,speech));assertFalse(VoicePolicy.interruptAllowed(true,false,true,mic,speech,speech,speech));assertFalse(VoicePolicy.interruptAllowed(true,true,false,mic,speech,speech,speech));assertFalse(VoicePolicy.interruptAllowed(true,true,true,mic,speech,speech,""));assertFalse(VoicePolicy.interruptAllowed(true,true,true,mic,speech,mic,speech));assertFalse(VoicePolicy.interruptAllowed(true,true,true,speech,speech,speech,speech));}
 @Test public void unavailableRequestedVoiceFallsBack(){java.util.List<String> voices=java.util.Arrays.asList("saved-but-unusable","hebrew","english");assertEquals("hebrew",VoicePolicy.firstUsable(voices,v->!v.startsWith("saved")));assertNull(VoicePolicy.firstUsable(voices,v->false));}
 @Test public void sessionBoundary(){assertTrue(VoicePolicy.validSession("voice-document123-42"));assertFalse(VoicePolicy.validSession(""));assertFalse(VoicePolicy.validSession("other-account"));assertFalse(VoicePolicy.validSession("voice-1/../../"));}
 @Test public void boundedStyles(){assertEquals(0.8f,VoicePolicy.delivery(0.1,0.8f,1.2f),0.001f);assertEquals(1.2f,VoicePolicy.delivery(5,0.8f,1.2f),0.001f);assertEquals(1f,VoicePolicy.delivery(Double.NaN,0f,1f),0.001f);assertEquals(0.82f,VoicePolicy.delivery(0.82,0f,1f),0.001f);}
 @Test public void actionableRecognitionErrors(){assertEquals("not-allowed",VoicePolicy.recognitionError(9));assertEquals("no-speech",VoicePolicy.recognitionError(7));assertEquals("network",VoicePolicy.recognitionError(2));assertEquals("language-not-supported",VoicePolicy.recognitionError(12));assertEquals("service-not-allowed",VoicePolicy.recognitionError(999));}
}
